const encoder=new TextEncoder();const bytes=s=>encoder.encode(s);
const crcTable=Uint32Array.from({length:256},(_,i)=>{for(let n=0;n<8;n++)i=i&1?0xedb88320^(i>>>1):i>>>1;return i>>>0;});
export function crc32(data){let crc=0xffffffff;for(const b of data)crc=crcTable[(crc^b)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function be32(n){const a=new Uint8Array(4);new DataView(a.buffer).setUint32(0,n);return a;}
function chunk(name,payload){const type=bytes(name),crc=crc32(new Uint8Array([...type,...payload]));return [be32(payload.length),type,payload,be32(crc)];}
export async function pngBlob(canvas,source,{widthCm=25}={}){const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('PNG 建立失敗；請降低圖檔尺寸。');const data=new Uint8Array(await blob.arrayBuffer()),parts=[data.subarray(0,8)];let offset=8;while(offset<data.length){const len=new DataView(data.buffer,data.byteOffset+offset,4).getUint32(0),type=new TextDecoder().decode(data.subarray(offset+4,offset+8));if(type!=='pHYs')parts.push(data.subarray(offset,offset+len+12));if(type==='IHDR'){const density=new Uint8Array(9),view=new DataView(density.buffer),ppm=Math.round(canvas.width/(widthCm/100));view.setUint32(0,ppm);view.setUint32(4,ppm);density[8]=1;parts.push(...chunk('pHYs',density),...chunk('iTXt',bytes('Description\0\0\0\0\0'+source)));}offset+=len+12;}return new Blob(parts,{type:'image/png'});}
export function pdfBlob(canvas,source,{widthCm=25,heightCm=20}={}){const url=canvas.toDataURL('image/jpeg',.97),jpeg=Uint8Array.from(atob(url.split(',')[1]),c=>c.charCodeAt(0));const w=widthCm/2.54*72,h=heightCm/2.54*72,content=`q\n${w} 0 0 ${h} 0 0 cm\n/Im0 Do\nQ\n`,safe=source.replace(/[^\x20-\x7e]/g,' ').replace(/[\\()]/g,'\\$&');let parts=[bytes('%PDF-1.4\n')],offset=parts[0].length,offsets=[0];function object(id,payload){offsets[id]=offset;const pre=bytes(`${id} 0 obj\n`),post=bytes('\nendobj\n'),arr=Array.isArray(payload)?payload:[bytes(payload)];parts.push(pre,...arr,post);offset+=pre.length+arr.reduce((n,p)=>n+p.length,0)+post.length;}
 object(1,'<< /Type /Catalog /Pages 2 0 R >>');object(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');object(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${w} ${h}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);object(4,[bytes(`<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpeg.length} >>\nstream\n`),jpeg,bytes('\nendstream')]);object(5,`<< /Length ${bytes(content).length} >>\nstream\n${content}endstream`);object(6,`<< /Producer (TaiwanBioTopoMaps Web) /Subject (${safe}) >>`);const xref=offset;parts.push(bytes(`xref\n0 7\n0000000000 65535 f \n${offsets.slice(1).map(x=>String(x).padStart(10,'0')+' 00000 n \n').join('')}trailer\n<< /Size 7 /Root 1 0 R /Info 6 0 R >>\nstartxref\n${xref}\n%%EOF\n`));return new Blob(parts,{type:'application/pdf'});
}
export async function zipBlob(files){let parts=[],central=[],offset=0;for(const file of files){const name=bytes(file.name),data=file.data instanceof Blob?new Uint8Array(await file.data.arrayBuffer()):typeof file.data==='string'?bytes(file.data):file.data,crc=crc32(data);const header=new Uint8Array(30),v=new DataView(header.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(12,0x21,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);parts.push(header,name,data);const c=new Uint8Array(46),cv=new DataView(c.buffer);cv.setUint32(0,0x02014b50,true);cv.setUint16(4,20,true);cv.setUint16(6,20,true);cv.setUint16(8,0x0800,true);cv.setUint16(14,0x21,true);cv.setUint32(16,crc,true);cv.setUint32(20,data.length,true);cv.setUint32(24,data.length,true);cv.setUint16(28,name.length,true);cv.setUint32(42,offset,true);central.push(c,name);offset+=header.length+name.length+data.length;}
 const size=central.reduce((n,p)=>n+p.length,0),end=new Uint8Array(22),ev=new DataView(end.buffer);ev.setUint32(0,0x06054b50,true);ev.setUint16(8,files.length,true);ev.setUint16(10,files.length,true);ev.setUint32(12,size,true);ev.setUint32(16,offset,true);return new Blob([...parts,...central,end],{type:'application/zip'});
}
export function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
export function safeName(s){let name=String(s).normalize('NFC').trim().replace(/[\\/:*?"<>|\x00-\x1f]/g,'_').replace(/\s+/g,'_').replace(/^\.+|\.+$/g,'');if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(name))name='_'+name;return Array.from(name).slice(0,80).join('').replace(/\.+$/g,'')||'MAP_TW';}
export function uniqueName(value,used){const base=safeName(value);let name=base,n=1;while(used.has(name.toLowerCase())){const suffix='_'+(++n);name=Array.from(base).slice(0,80-suffix.length).join('')+suffix;}used.add(name.toLowerCase());return name;}
